<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowUpRight, Mail, Phone, MapPin, Check, Copy } from 'lucide-vue-next'
import { useClipboard } from '@vueuse/core'
import { company, services } from '../data'
import SectionLabel from '../components/SectionLabel.vue'
const { copy, copied, isSupported } = useClipboard()
const form = ref({ name: '', company: '', email: '', phone: '', service: '', message: '' })
const draftReady = ref(false)
const body = computed(() => `姓名：${form.value.name}\n公司：${form.value.company}\nEmail：${form.value.email}\n電話：${form.value.phone}\n需求類型：${form.value.service || '一般諮詢'}\n\n${form.value.message}`)
const mailLink = computed(() => `mailto:${company.contactEmail}?subject=${encodeURIComponent(`[網站諮詢] ${form.value.service || '技術需求'} — ${form.value.name}`)}&body=${encodeURIComponent(body.value)}`)
function prepare() { draftReady.value = true }
</script>
<template><section class="page-hero container"><SectionLabel number="05" label="LET’S CONNECT" /><div class="page-hero-grid"><h1 data-reveal>說說您的想法，<br /><span class="accent">一起找到方向。</span></h1><p class="page-hero-copy" data-reveal>無論是明確的技術需求，或初步的專案構想，<br />歡迎與爵邁聯繫。</p></div></section><section class="contact-section section-space"><div class="container contact-grid"><div class="contact-information" data-reveal><SectionLabel label="GET IN TOUCH" /><h2>{{ company.name }}</h2><p class="eyebrow">DRAGON MILE CO., LTD.</p><dl><div><dt><Phone :size="18" /> 公司電話</dt><dd><a href="tel:075523561">{{ company.phone }} <ArrowUpRight :size="17" /></a><a href="tel:+886910921303" class="secondary-contact">{{ company.mobile }}（專案聯絡）</a></dd></div><div><dt><Mail :size="18" /> 電子信箱</dt><dd><a :href="`mailto:${company.contactEmail}`">{{ company.contactEmail }} <ArrowUpRight :size="17" /></a><a :href="`mailto:${company.email}`" class="secondary-contact">{{ company.email }}</a></dd></div><div><dt><MapPin :size="18" /> 公司地址</dt><dd><a href="https://maps.google.com/?q=高雄市鼓山區明華路251號" target="_blank" rel="noopener noreferrer">{{ company.address }} <ArrowUpRight :size="17" /></a></dd></div></dl><div class="contact-coordinate"><span>KAOHSIUNG</span><span>TAIWAN ↗</span></div></div><div class="contact-form-wrap" data-reveal><SectionLabel label="PROJECT INQUIRY" /><h2>與我們分享需求</h2><p class="form-intro">填寫以下資訊以建立郵件草稿，再由您的郵件程式寄出。</p><form @submit.prevent="prepare"><div class="form-grid"><label>姓名 <span>*</span><input v-model="form.name" name="name" autocomplete="name" required maxlength="100" placeholder="如何稱呼您" /></label><label>公司名稱<input v-model="form.company" name="organization" autocomplete="organization" maxlength="150" placeholder="您的公司或單位" /></label><label>電子信箱 <span>*</span><input v-model="form.email" type="email" name="email" autocomplete="email" required maxlength="254" placeholder="name@company.com" /></label><label>聯絡電話<input v-model="form.phone" type="tel" name="phone" autocomplete="tel" maxlength="40" placeholder="方便聯繫的電話" /></label></div><label>需求類型<select v-model="form.service" name="service"><option value="">請選擇服務項目</option><option v-for="s in services" :key="s.slug">{{ s.title }}</option><option>企業系統與其他技術需求</option></select></label><label>需求說明 <span>*</span><textarea v-model="form.message" name="message" required rows="5" maxlength="5000" placeholder="簡單說明您的專案背景與技術需求…" /></label><p class="form-note">此表單不會自動送出或儲存資料。您可先檢視草稿，再開啟郵件程式寄送。</p><button type="submit" class="button">建立諮詢郵件 <ArrowUpRight :size="18" /></button></form><div v-if="draftReady" class="draft-preview" role="status"><span class="eyebrow"><Check :size="16" /> 郵件草稿已備妥</span><p>收件人：{{ company.contactEmail }}</p><pre>{{ body }}</pre><div class="draft-actions"><a :href="mailLink" class="button">開啟郵件程式 <ArrowUpRight :size="17" /></a><button v-if="isSupported" class="text-link" @click="copy(body)"><Check v-if="copied" :size="16" /><Copy v-else :size="16" />{{ copied ? '已複製' : '複製內容' }}</button></div></div></div></div></section></template>
